"""Closeout from frozen labels and preserved provider evidence; never rescores."""
from collections import Counter,defaultdict
from datetime import datetime,timezone
import json
import math
from pathlib import Path
import statistics
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from experiments.pr_eg_r6_r4_r1.run import OUT,read,dump,sha,verify,families
from experiments.pr_eg_r6_r4_r1 import engine as E


def fraction(k,n):return f'{k}/{n} ({100*k/n:.1f}%)' if n else '0/0 (not measured)'
def p95(v):return sorted(v)[max(0,math.ceil(.95*len(v))-1)] if v else None
def describe(v):return dict(n=len(v),total=sum(v),mean=statistics.mean(v) if v else None,p95=p95(v))
def doc(n,title,body):
    p=OUT/f'{n:02}_{title.upper().replace(" ","_").replace("/","_")}.md'
    p.write_text(f'# {n:02} — {title}\n\n{body.strip()}\n',encoding='utf-8')


def aggregate(rows,cases):
    stats={}
    for arch in 'ABC':
        rs=[r for r in rows if r['architecture']==arch]
        metrics={k:sum(r['scores'][k] for r in rs) for k in ('answer_success','class_correct','content_correct','qualifier_preserved','false_acceptance','false_rejection','unsupported_inference')}
        metrics['n']=len(rs)
        metrics['answerable']=sum(cases[r['case_id']]['expected']['response_class'] in {'DIRECT','PARTIAL'} for r in rs)
        metrics['positive_predictions']=sum(r['answer']['response_class'] in {'DIRECT','PARTIAL'} for r in rs)
        metrics['gated_success']=sum(bool(r['scores']['answer_success'] and r['gate'].get('candidate_eligible',False)) for r in rs)
        metrics['gated_false_acceptance']=sum(bool(r['scores']['false_acceptance'] and r['gate'].get('candidate_eligible',False)) for r in rs)
        metrics['classes']={c:dict(n=len(sub:=[r for r in rs if cases[r['case_id']]['expected']['response_class']==c]),success=sum(r['scores']['answer_success'] for r in sub)) for c in ('DIRECT','PARTIAL','RELATED_NONANSWER','UNKNOWN')}
        metrics['earliest_failures']=dict(Counter(r['scores']['earliest_failure'] for r in rs if r['scores']['earliest_failure']))
        metrics['provider_errors']=dict(Counter(r['provider_error'] for r in rs if r['provider_error']))
        stats[arch]=metrics
    return stats


def main():
    verify();fs=families();cases={c['id']:c for f in fs for c in f['cases']}
    rows=[read(p) for p in sorted((OUT/'results').glob('*.json'))]
    if len(rows)!=510:raise RuntimeError('Incomplete primary experiment')
    stats=aggregate(rows,cases)
    strata={k:aggregate([r for r in rows if r['partition']==k],cases) for k in ('development','validation','holdout')}
    context={k:aggregate([r for r in rows if r['context']==k],cases) for k in ('short','long')}
    cat={k:aggregate([r for r in rows if cases[r['case_id']]['category']==k],cases) for k in sorted({c['category'] for c in cases.values()})}
    paired={}
    by={(r['case_id'],r['architecture']):r for r in rows}
    for left,right in [('A','B'),('A','C'),('B','C')]:
        paired[left+right]=dict(left_only=sum(by[c,left]['scores']['answer_success'] and not by[c,right]['scores']['answer_success'] for c in cases),
            right_only=sum(by[c,right]['scores']['answer_success'] and not by[c,left]['scores']['answer_success'] for c in cases),
            both=sum(by[c,left]['scores']['answer_success'] and by[c,right]['scores']['answer_success'] for c in cases))
    calls=[(p,read(p)) for p in sorted((OUT/'calls').glob('*.json'))]
    (OUT/'provider_calls.jsonl').write_text(''.join(json.dumps(dict(path=p.relative_to(ROOT).as_posix(),record=r),ensure_ascii=False)+'\n' for p,r in calls),encoding='utf-8')
    (OUT/'extraction_records.jsonl').write_text(''.join(json.dumps(dict(path=p.relative_to(ROOT).as_posix(),record=read(p)),ensure_ascii=False)+'\n' for p in sorted((OUT/'extractions').glob('*.json'))),encoding='utf-8')
    perf={}
    for arch in 'ABC':
        ar=[(p,r) for p,r in calls if p.stem.endswith('_'+arch)]
        perf[arch]={}
        for phase in ('extract','results','all'):
            rs=[r for p,r in ar if phase=='all' or p.name.startswith(phase+'_')]
            perf[arch][phase]=dict(calls=len(rs),successful=sum(bool(r.get('parsed')) for r in rs),
                input_tokens=describe([r['usage']['input_tokens'] for r in rs if r.get('usage')]),
                output_tokens=describe([r['usage']['output_tokens'] for r in rs if r.get('usage')]),
                latency_ms=describe([r['latency_ms'] for r in rs]))
        perf[arch]['amortized_tokens_per_question']={k:perf[arch]['all'][k]['total']/170 for k in ('input_tokens','output_tokens')}
        perf[arch]['context']={ctx:dict(calls=len(cr:=[r for p,r in ar if p.name.startswith('results_') and by[p.stem[len('results_'):-2],arch]['context']==ctx]),
            input_tokens=describe([r['usage']['input_tokens'] for r in cr if r.get('usage')]),
            output_tokens=describe([r['usage']['output_tokens'] for r in cr if r.get('usage')]),
            latency_ms=describe([r['latency_ms'] for r in cr])) for ctx in ('short','long')}
    ext={};reuse=[]
    for arch in 'BC':
        records=[read(p) for p in (OUT/'extractions').glob('*_'+arch+'.json')]
        facts=[x for r in records for x in r['records']]
        ext[arch]=dict(extraction_calls=sum(r['provider_call'] for r in records),sources=sum(len(r['source_ids']) for r in records),
            proposed_facts=len(facts),levels=dict(Counter(x['validation']['level'] for x in facts)),
            reasons=dict(Counter(y for x in facts for y in x['validation']['reasons'])))
        gold_roles=matched_roles=exact_name_roles=gold_qualifiers=matched_qualifiers=0
        for f in fs:
            if not E.eligible(f['sources'],f['cases'][0]['npc'],'experiment'):continue
            extracted=read(OUT/'extractions'/f'{f["family"]}_{arch}.json')
            props=[x['fact'] for x in extracted['records']]
            for source in f['sources']:
                for claim in source['supported_claims']:
                    for role,value in claim['roles'].items():
                        gold_roles+=1
                        matches=[r for p in props if p['source_id']==source['id'] for r in p['roles'] if E.normalize(r['value'])==E.normalize(value)]
                        matched_roles+=bool(matches);exact_name_roles+=any(r['name']==role for r in matches)
                    for q in claim['qualifiers']:
                        gold_qualifiers+=1
                        matched_qualifiers+=any(q in p['qualifiers'] or q==p['temporal'] or q==p['spatial'] for p in props if p['source_id']==source['id'])
            hashes={by[c['id'],arch]['extraction_hash'] for c in f['cases']}
            current=sha(OUT/'extractions'/f'{f["family"]}_{arch}.json')
            reuse.append(dict(family=f['family'],architecture=arch,source_ids=extracted['source_ids'],questions=5,
                hashes=sorted(hashes),current_hash=current,unchanged=hashes=={current},reextractions=0,
                successes=sum(by[c['id'],arch]['scores']['answer_success'] for c in f['cases'])))
        ext[arch]['reference_diagnostics']=dict(gold_role_values=gold_roles,role_value_coverage=matched_roles,exact_role_name_agreement=exact_name_roles,
            gold_qualifier_phrases=gold_qualifiers,qualifier_phrase_coverage=matched_qualifiers,
            semantic_precision=None,semantic_recall=None,reason='Sparse pre-authored claims, open relation names and unreviewed extra facts prevent defensible entailment precision/recall.')
    dump(OUT/'summary.json',dict(primary=stats,partitions=strata,contexts=context,categories=cat,paired=paired,
        metric_interpretation='Frozen false_acceptance/unsupported_inference are strict answer-rubric flags, not measured source-entailment errors. Full-sentence values can be source-supported yet off-rubric. No post-exposure rescoring.',
        performance=perf,extraction=ext,verdict='C — INCONCLUSIVE / BELOW ACCEPTANCE',human_adjudication='pending'))
    dump(OUT/'reuse_results.json',reuse)
    (OUT/'per_case_results.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')
    baseline=read(OUT/'baseline.json');freeze=read(OUT/'freeze.json');security=read(OUT/'security_results.json');payload=read(OUT/'payload_audit.json')
    table='| Arm | Strict case agreement | Class agreement | Exact content agreement | Rubric acceptance flags | Off-rubric positive predictions |\n|---|---:|---:|---:|---:|---:|\n'
    for a,s in stats.items():
        table+=f'| {a} | {fraction(s["answer_success"],s["n"])} | {fraction(s["class_correct"],s["n"])} | {fraction(s["content_correct"],s["n"])} | {fraction(s["false_acceptance"],s["positive_predictions"])} | {fraction(s["unsupported_inference"],s["positive_predictions"])} |\n'
    verdict='**C — INCONCLUSIVE / BELOW ACCEPTANCE. Do not integrate.** Reuse works as caching, but source anchoring does not establish semantic support. Human adjudication and defensible semantic extraction precision/recall are missing. No production migration or PR-EH work was performed.'
    summary=verdict+'\n\n'+table+'\nStrict agreement requires frozen class, exact normalized answer values and required literal qualifiers. These are offline candidate predictions, never delivered facts. The frozen scorer flags full-sentence answers as extra values even when their source supports them: its false_acceptance/unsupported_inference fields are rubric flags, NOT measured semantic falsehood rates. No corrected scores replace frozen results. Zero canonical promotion and zero gameplay disclosures occur by construction, not evidence that predictions are safe to deploy. See 31 for metric limitations and 33 for dependence/label uncertainty.'
    doc(1,'Executive Summary',summary)
    doc(2,'Repository Baseline',f'Commit `{baseline["commit"]}`, branch `{baseline["branch"]}`.\n\n```text\n{baseline["log"]}\n```\n\nCheckpoint 4320bcd and CI maintenance 588531e/b012c3d are present in ancestry. No history operations. Baseline working tree is extensively dirty; full status is preserved in baseline_status.txt. Existing changes were not reset. Model {baseline["model"]}, temperature 0, output cap 1800, no SDK retries. Actual provider model IDs are in raw responses. Every file under game/ and data/ is hashed before/after; production_integrity.json confirms the comparison. Local .env credentials are loaded by game.config but never serialized.')
    hist=read(OUT/'historical_inventory.json');hx=[json.loads(l) for l in (OUT/'historical_examples.jsonl').read_text(encoding='utf-8').splitlines()]
    observations='\n'.join(f'- {x["cycle"]}: `{x["path"]}:{x["line"]}` — {x["observation"]}' for x in hx)
    doc(3,'Historical Failure Review',f'{len(hist)} original JSONL files inventoried across R2, R2-R1, R2-R2, R3, R3-R1 and R4; {len(hx)} raw records re-opened with file hashes and line numbers.\n\n{observations}\n\nR2 empty source propositions with a question interpretation are observed omissions; wrong-source vs wrong-question causality needs the available-source snapshot. R4 primary uses gold question meanings and secondary actual meanings: they cannot be pooled. Vocabulary/role mismatch can deterministically reject a valid paraphrase in named_coverage; it is a mechanism, not a claim that every historical UNKNOWN had that cause. Historical raw evidence does not establish all requested false-DIRECT/provenance categories; unobserved categories remain unverified.')
    doc(4,'Current Semantic Pipeline','Ordinary NPC topic prose enters `_topic_rows` (game/unified_semantic_planning.py:665). Host disclosure policy gates candidate text. `_provider_context`:422 compacts visible sources/history; `_invoke_provider`:460 jointly proposes request and up to four source propositions using open predicate/role names. `clean_proposition` validates schema; witnessed/roles_witnessed require literal evidence and host-known aliases. `coverage` and `named_coverage` compare predicate names, role names/values, negation, scope and epistemic status deterministically. Sufficiency depends on the requested role being present. `authorize_information_turn`:782 binds host-owned conversational references and rechecks source eligibility; final delivery is sealed by game/immutable_valid_response.py.\n\nOnly interpretation needs a provider call; eligibility, syntax, correspondence, sufficiency, authorization and sealing are host stages. Predicate/role names remain AI proposals. Exact names, missing values and epistemic mismatch reject valid evidence; literal anchors cannot prevent wrong role labels or epistemic strengthening. A runs the production prompt/schema/coverage kernel with captured transport, not the full API, routing, authorization or emission pipeline.')
    doc(5,'Experimental Hypothesis','Extract once from ordinary authorized prose, reuse the unchanged representation across five independent questions, improve answer recovery without more unsupported candidate claims. Frozen falsifiers include role/qualifier loss, unsupported implications, unfamiliar relation failure, costly review or no amortized savings. Caching success alone does not support semantic adequacy. Contract and labels predate all successful provider execution.')
    doc(6,'Architecture Specifications','A: current production system prompt and proposal schema, source prose interpreted per question, unchanged correspondence kernel. B: one provider extraction per family, structure/source-availability checks, immutable cached facts; one raw-question alignment per question. C: same extraction and alignment contracts, plus mechanical span/argument/scope/authority/identity validation before facts reach alignment. Separate B/C extractions introduce stochastic differences, so C-versus-B is not a pure paired-validator ablation. Both apply a post-alignment candidate anchor gate.\n\nNo arm delivers a response or grants world authority. A/B/C differ in output representation capacity; the single-proposition A contract can lose conjunctions. Report contract effects rather than claiming a universal algorithmic improvement. CONTRACT.md is the full preregistered protocol.')
    doc(7,'Source Extraction Contract','`engine.FACT` requires local fact ID, host source ID, open relationship name, named roles with literal value/evidence, unknown roles, qualifier phrases, negation, temporal/spatial scope, epistemic status, provenance and source evidence span. A source may yield several facts. No fixed global relationship ontology or phrase-specific matching rules. Human-reviewed entailment and canonical authority are absent. A communication event/content link is not a first-class typed reference in this prototype; this is a discovered limitation, not a production-ready schema.')
    doc(8,'Multi-Fact Sources','s01 separates communication, reported content and absence of inspection. s03 includes a negative sale and positive loan; s24 includes delegated duty and retained authority. Extracted facts are preserved in extractions/. Inspect s01_C: the cistern property proposition is anchored but lacks an explicit reported-content link. Its source epistemic is inherited as npc_knowledge, which does not prove the property true. Host anchoring cannot repair this semantic loss. Multi-fact extraction count and review status are in summary.json; no sparse gold annotation is treated as an exhaustive source inventory.')
    doc(9,'Qualifier Preservation','Families cover may (s08), might (s09), probably (s07), reportedly (s02), used to (s04), will/if (s05), unless (s06), not (s30), spatial boundaries (s14/s31), and ledger attribution (s25). Frozen labels demand literal required phrases in positive answers. Qualifier_phrase_coverage in summary.json measures annotated source phrases appearing in extracted fields, not correct semantic scope. A paraphrase such as a synonymous modal can fail this strict rubric; labels were not corrected after exposure. Lost epistemic force and wrong temporal attachment need human review.')
    doc(10,'Provenance and Authority','Source provenance and epistemic metadata are host-owned. world_source, host_operation and bounded_expression can be eligible under host disclosure policy; verified_history is excluded from world-evidence extraction. Actual corpus includes world sources, authorized noncanonical narration, beliefs, rumor, disputed reports and historical speech. Security probes cover all four required provenance labels. No new host_operation campaign evidence is invented. C compares provenance/epistemic to the original eligible source. Authorization is not canonical status; source authority cannot be promoted by confidence or human review.')
    doc(11,'Host Validation','Mechanically checked: known source identity, NPC/context membership, existing host disclosure policy, schema/duplicate fact IDs, evidence-span substring, role-value-within-role-evidence-within-span, literal qualifier/scope anchors, inherited authority metadata, selected fact/source coherence, answer-value anchors. Not mechanically established: relation entailment, role direction, omission of an essential qualifier, implicit causal support, metaphor literalness or reported-content truth. A named-role swap can pass all anchors. These are separate measurements; no host_verified semantic label is assigned.')
    doc(12,'Validation Trust Levels','STRUCTURALLY_VALID: schema and source access passed (B). SOURCE_ANCHORED: C literal/metadata constraints passed. SEMANTICALLY_SUPPORTED: requires a trusted entailment procedure or bounded proof; not reached here. HUMAN_REVIEWED: requires an actual reviewer record; none exists. REJECTED: mechanical check failed. Human review does not itself change canonical authority. All extracted facts remain proposals; all candidate outputs carry delivery_authorized=false and canonical=false.')
    doc(13,'Question Alignment','Primary inputs contain raw player questions and eligible evidence only. No gold role names, expected values, classes, forbidden claims or supported_claims enter primary requests; payload_audit.json scans all saved requests. B/C align against cached facts and their evidence spans without the original source prose or re-extraction. The separate offline gold diagnostic uses only frozen known question roles, requested role names and relationship. It replays exact relation/role unification against saved source interpretations and cannot measure a provider semantic bridge. Network gold diagnostic was not executed because automatic approval review rejected the additional metadata payload. Do not invoke the frozen runner diagnostic network mode; use tools/diagnostic_pr_eg_r6_r4_r1.py.')
    doc(14,'Multi-Role Alignment','Speaker/recipient/message: s01. Owner/borrower: s18. Creditor/debtor: s13/s19. Buyer/seller: s17. Guard/protected party: s10/s30. Unfamiliar roles include licensor/licensee, guarantor, recognizer, hereditary right holder, redeemer/tender/compensation, voucher/certified object, sentence commuter, impounder and delegator/delegate. Reversed speaker/recipient or simultaneous buyer/seller swaps are negative questions. Exact requested answer values detect many directional errors; arbitrary extracted role-name equivalence is not reliably scored without adjudication. The reference role-name metric is labeled exact agreement, not semantic role preservation.')
    doc(15,'Partial Answers','Every ordinary positive source family includes a conjunction with a missing role, amount, reason, date or informant. Bridge guard and shift schedule are s10q3. The prediction must return PARTIAL and only the allowed answering values while naming unanswered arguments. Raw answered_arguments and missing_arguments are preserved; exact correctness of their arbitrary role names remains unadjudicated. A single-request proposition can return DIRECT to only the first conjunct and fails the frozen class rubric. Conflict questions are PARTIAL, not silently settled world facts. See class-specific counts in summary.json.')
    doc(16,'Related Nonanswers','s11q3 asks who supplied a road name; the source supplies the name and destination but no informant. Other negatives distinguish custody/protection, creditor/debtor, former/current work and lending/sale. A response that merely concerns the same entity is not correct. UNKNOWN versus RELATED_NONANSWER disagreements count as strict class errors even if both decline to invent. This boundary has label uncertainty; see the unchanged frozen questions and human review packet. No post-exposure safe-response credit was added.')
    doc(17,'Conflicting Evidence','s25 has two host source IDs: morning ledger says intact, evening ledger says collapsed. Both remain disputed reports, not automatically true; timing and attribution survive separately. q0/q1 require PARTIAL and both values with both ledger attributions; q2/q4 explicitly ask for one ledger. The corpus tests attributed temporal disagreement, not proven simultaneous canonical contradiction. No source is silently promoted, and the host does not choose world truth from provider selection.')
    doc(18,'Open-World Generalization','No relationship registry was added. Licensing, debt guarantee, sanctuary, hereditary rights and reporting lines accompany redeeming beads, vouching for weights, commuting exile, impounding a barge, delegating a task and ratifying a compact. Category results are in summary.json. All families were authored by the same agent before provider runs; no prompt tuning occurred, but only 11 families are held out. This is unseen-from-tuning source-family testing, not proof of broad campaign generalization or an independently collected real-play sample.')
    partitions={p:dict(families=sum(f['partition']==p for f in fs),cases=sum(len(f['cases']) for f in fs if f['partition']==p)) for p in ('development','validation','holdout')}
    doc(19,'Corpus Design',f'170 manually authored questions; 34 distinct source families, 35 source records, 3 NPC profiles. Thirty fully eligible families contain 31 source records and five questions each. Four families test denied history/private/password/countersign evidence. Semantic situations are hand-written, not repeated template expansions. This is realistic synthetic prose, not sampled live campaign data.\n\nPartitions: `{json.dumps(partitions)}`. Each family, including its two conflict records, stays in one partition. Categories and pre-authored claims/permissions reside in frozen partition JSON files.')
    doc(20,'Reuse Experiment',f'{len(reuse)} eligible family-arm bundles each have five primary questions; {sum(r["unchanged"] for r in reuse)}/{len(reuse)} preserve the identical extraction file hash for every question and the final artifact. B and C each extract 31 source records through 30 family-batch calls. Re-extraction frequency is 0 after initial successful extraction; first question populates the cache, four later questions reuse it. Cache hits are 120/150 eligible question-arm requests for each arm. Denied families have empty facts and are not credited as useful extraction reuse. Per-family success, source IDs and hashes are in reuse_results.json. Failed network attempts are separately preserved and excluded from successful-call reuse claims.')
    doc(21,'Frozen Partitions',f'Freeze timestamp: {freeze["created_at"]}. SHA-256 covers corpus.py, engine.py, run.py, CONTRACT.md, all partitions and the production correspondence/authorization dependencies. Frozen input count {len(freeze["hashes"])}. No partition, label, prompt, scorer or adapter amendments after freeze. verify() checks every hash plus all game/data hashes at each run boundary. Development ran first, then validation/holdout, without tuning. The report and read-only offline diagnostic were written after exposure; they do not alter primary outputs or scoring. Hashes prove preservation after authoring, not that an AI author never saw its own holdout.')
    doc(22,'Ground Truth','Pre-provider labels specify expected answer class, exact allowed answer values, mandatory qualifiers, forbidden content, question diagnostic representation and source-supported claim/role annotations. Host source records define provenance, NPC membership, context and disclosure. Supported-claim annotations are sparse and not exhaustive. Labels come from the author independently of model responses; they are not independently human reviewed. Runtime adapters never read labels to decide candidate answers. Exact content, required phrases and class determine frozen scores; forbidden values are rejected through allowed-value set comparison for positive answers. Reasons and missing-argument prose are ungraded, so do not treat all generated text as verified.')
    review=[]
    for f in fs:
        for c in (f['cases'][0],f['cases'][3 if int(f['family'][1:])%2==0 else 4]):
            review.append(dict(case=c,sources=f['sources'],outputs={a:by[c['id'],a] for a in 'ABC'},review_status='pending',reviewer=None))
    dump(OUT/'human_review_packet.json',dict(sample_strategy='Every category q0 plus alternating q3/q4, covering DIRECT/PARTIAL/RELATED_NONANSWER/UNKNOWN',
        cases=review,human_adjudication='pending',instructions='Judge labels and proposals separately. Record disagreements without editing frozen labels. No gold-derived output qualification.'))
    doc(23,'Human Adjudication Packet',f'Independent human adjudication is **pending**. The frozen pre-run packet includes 34 category-stratified q0 cases; human_review_packet.json supplies {len(review)} cases with sources, labels and all three outputs, adding alternating partial/nonanswer questions. Suggested review fields: supported class/content, uncertainty, reported-speech truth, role direction, authority, missing roles and grader disagreement. No reviewer names, decisions, minutes or agreement rates are invented. Conclusions about strict label agreement are reproducible; conclusions about semantic precision, recall, authoring burden and deployment suitability require review.')
    doc(24,'Experimental Fairness','Identical source eligibility, NPC/context, model, temperature, output cap, no retries and raw questions across arms. A receives prose each time; B/C receive their own immutable extracted representation. Extraction overhead is counted. Each arm sees identical inert history per case. Long versus short strata are deliberately reported but confounded with question type, not randomized history treatments. A prompt/schema/coverage remain current production; B/C have a richer multi-fact/multi-value answer contract. B/C separate extraction samples and C validator differences both affect outcomes. No gold hints in primary; no post-exposure rescoring, ambiguity exclusions, holdout modifications or best-of sampling.')
    provider_ok=sum(bool(r.get('parsed')) for p,r in calls)
    blocked=list((OUT/'attempts/blocked_network/calls').glob('*.json'))
    doc(25,'Provider Evidence',f'{len(calls)} authorized logical/physical request attempts; {provider_ok}/{len(calls)} parsed responses. Model requests use {baseline["model"]}; actual version IDs, response IDs/status, raw text/object, parsed results, usage, latency and exact request bodies/schema are in calls/. Authorization headers are never saved. No mocked response is included in qualification. SDK retries are disabled. Earlier network-blocked attempts ({len(blocked)}) remain under attempts/blocked_network with no fabricated usage and are excluded from provider quality metrics. Explicit user approval enabled the primary run. Additional network gold metadata diagnostic was rejected and replaced by a zero-call local control.')
    taxonomy=['Unsupported extracted fact','Missing supported fact','Wrong relationship','Wrong semantic role','Lost qualifier','Lost negation','Epistemic strengthening','Source identity mismatch','Evidence span mismatch','Question interpretation error','Semantic alignment error','False direct answer','False partial answer','Related nonanswer accepted','Valid answer rejected','Unsupported inference','Authorization failure','Provenance failure','Evaluation disagreement','Excessive cost']
    doc(26,'Failure Taxonomy','\n'.join(f'- F{i:02}: {t}.' for i,t in enumerate(taxonomy,1))+'\n\nThe frozen scorer assigns only observable coarse F05/F11/F15/F16 outcomes, not every requested root cause. These are earliest *detectable scoring failures*, not proven earliest semantic causes. Source/request role errors, reported-content promotion and missing arguments require manual causal audit. Per-case raw outputs and validation reasons are preserved; no invented comprehensive causal attribution is reported.')
    doc(27,'Security Experiments',f'Deterministic adversarial checks: {security["passed"]}/{security["total"]}. They cover disclosure denial, private knowledge, foreign NPC/conversation, historical laundering, forged IDs, fabricated spans/arguments and authority inheritance. Role-swap anchoring is deliberately shown to remain semantically unverified. Primary provider payload audit: {payload["unavailable_source_leaks"]}/{payload["calls"]} unavailable-source text exposures and {payload["oracle_leaks"]}/{payload["calls"]} gold-field leaks. Password/countersign paraphrases and unsupported clue questions run with empty source context. These counts concern this finite synthetic corpus and saved payloads, not universal security. No generated value reaches world state or final emission.')
    doc(28,'Host Validation Results',f'```json\n{json.dumps(ext,indent=2)}\n```\n\nStructural validity, anchoring and semantic support are different axes. C accepted anchor level never exceeds SOURCE_ANCHORED. A role swap passes anchors; reported-speech extraction can lose its content link. Every semantic claim still needs trusted support, even when source identity and spans are mechanically valid. Per-fact reasons reside in extractions/. Candidate gate counts are in summary.json, and do not authorize delivery.')
    doc(29,'Annotation Cost','Human source preparation, extraction review, corrections, role ambiguity resolution and qualifier resolution were not measured: no human reviewer participated. Human minutes/source, minutes/accepted fact, intervention rate and correction frequency are **unavailable**, not zero. Provider processing time is measured in calls/ and performance metrics. Scenario planning only: at 1–3 review minutes/source, 31 eligible records imply 31–93 initial minutes, excluding corrections; this assumption is not observed labor. Campaign authoring burden remains unqualified. Full semantic annotations were not supplied to the runtime provider.')
    doc(30,'Performance',f'```json\n{json.dumps(perf,indent=2)}\n```\n\nAll phases include observed usage and request wall latency; parallel latency sums are not end-user elapsed latency. Mean/p95 use nearest-rank p95 and are separated by short/long contexts. Mean amortized tokens include extraction overhead across all 170 questions; eligible-only denominator is 150 and can be recomputed from raw records. Each B/C family extraction call may contain two conflict sources. Caching reduces re-extraction calls but still requires one alignment call/question. Dollar cost is not claimed because no current or account-specific unit price was verified. For any verified rates Pin/Pout per million, cost=(input_tokens*Pin+output_tokens*Pout)/1e6. No unsupported dollar savings claim or production affordability conclusion.')
    doc(31,'Quality Metrics',table+'\n\nExact numerators/denominators for class strata, partitions, contexts, categories, false rejections and gate-eligible candidate errors are in summary.json. Direct recovery uses the expected DIRECT denominator; partial correctness uses PARTIAL; related-nonanswer rejection uses exact RELATED_NONANSWER class agreement. qualifier_preserved is vacuous on negative cases with no required qualifiers; do not interpret its all-case rate as qualifier fidelity. Unsupported inference counts positive candidate classes/values outside frozen answers; missing literal qualifiers is a separate false-acceptance cause. Frozen exact-match values/phrases can overstate semantic failures.\n\nExtraction semantic precision/recall, fully general role preservation, implicit entailment and semantic generalization remain unmeasured pending adjudication. Reference exact-role-value/qualifier coverage is a transparent diagnostic, not a substitute. No denominator invents reviewed claims. Reuse is demonstrated structurally; successful semantic reuse is each family\'s 0–5 answer successes, not universal extraction correctness.')
    doc(32,'Comparative Results',table+f'\nPaired outcomes (left-only/right-only/both successes):\n```json\n{json.dumps(paired,indent=2)}\n```\n\nCompare both raw candidate quality and candidate-gated quality. C gate-eligible strict successes and errors are in summary.json; A has no matching post-alignment gate, so gated A is not comparable. No arm is credited with factual delivery safety from the universal delivery block. Complexity/review burden increases with role and qualifier contracts. Open vocabulary works syntactically but no architectural winner satisfies the semantic/security/cost decision criteria.')
    doc(33,'Statistical Limitations','170 paired questions, 34 family clusters, 35 source records, 31 eligible records; 3 NPC profiles and 34 categories. Five questions per family are correlated; they are not 170 independent source situations. Holdout has 11 families/55 questions. Same author designed sources, labels and partitions; no independent human adjudication or blinding. Exact class, literal qualifier and short answer value judgments can be disputed. Synthetic prose, fixed assignment and single provider sample limit external validity. B/C separate extraction samples, different A output expressiveness, and history/question-type confounding limit causal conclusions. No question-level confidence interval is presented as independent-source evidence. Gold diagnostic is offline and exact-vocabulary only. Human review burden, semantic precision/recall and dollar cost remain unknown.')
    doc(34,'Architecture Decision',verdict+'\n\nNo recommendation to integrate B or C. Immutable cache reuse and mechanically anchored provenance are feasible, but unsupported candidate claims, qualifier loss, role-schema mismatch and unreviewed labels prevent meeting the acceptance criteria. Development, validation and holdout results remain separate. No winner is forced. C (below acceptance) is a cycle verdict about evidence/criteria, not a claim of a catastrophic production blocker.')
    doc(35,'Production Integration Readiness','No integration implemented. A future boundary would accept only host-authorized source versions and expose noncanonical, versioned fact proposals, evidence offsets, unknown-role slots, scope operators and explicit reported-content edges. Cache keys need source content hash, NPC/context authorization scope, contract/model versions and invalidation on disclosure/source changes. Host reauthorization must occur before provider extraction, alignment and delivery. A disabled feature flag alone would not prove semantic support. Persist proposals outside world state; never mutate durable referents or final-response seals. Required qualification: independent reviewed fresh family holdouts, semantic-role/qualifier proofs or a reliable reject boundary, contradiction attribution, scoped caching, leakage tests, reviewed cost/labor and end-to-end final delivery regressions.')
    doc(36,'Remaining Unknowns','Can a useful semantic bridge preserve role direction without gold relation names? Can reported-content attribution be represented without promotion? Can qualifier omission be detected outside lexical lists? What trusted process establishes semantic support without expensive manual annotations? What are semantic precision/recall on exhaustive labels? Which strict-match failures are evaluator disagreement? How much human review and correction does each source need? What does an actual long campaign context cost? Can the A and B/C output contracts be fairly equalized? Is caching useful enough after ongoing alignment calls and invalidation? These questions remain open.')
    doc(37,'Recommended Next Cycle','Await external review. If a further discovery cycle is authorized, obtain independent adjudication first; preserve this frozen corpus for historical comparison and create new source-family holdouts after preregistering an exhaustive claim/role/scope rubric. Develop explicit reported-content links and a bounded semantic support boundary on development-only sources, then test a paired same-extraction C validator ablation and equalized A answer capacity. Use measured review labor and verified provider pricing. No next cycle or PR-EH is started here.')
    doc(38,'Final Verdict',verdict+'\n\nA/B verdict requirements are not met: reusable extraction is demonstrated, but independent semantic ground truth review, reliable entailment/roles, low unsupported predictions, authoring burden and dollar cost qualification remain unresolved. Real provider evidence and unchanged primary freeze are present. Offline gold diagnostic is explicitly separate and weaker than a provider-based control.')
